brand_css_dark:
:root {
  /* Primary - Active Red (다크 기본) */
  --color-primary-50:  #2A1414;  /* (추정) #FD312E 12% 를 #0F0F0F 에 합성 — 강조 행 배경 */
  --color-primary-100: #3A1716;  /* (추정) */
  --color-primary-200: #5A1C1A;  /* (추정) */
  --color-primary-300: #8E2220;  /* (추정) */
  --color-primary-400: #C42623;  /* (추정) */
  --color-primary-500: #FD312E;  /* 공식 Active Red — 다크에서 슬로건·강조·가격 */
  --color-primary-600: #FD312E;  /* 다크 채움색(버튼) — 어두운 바탕에선 원색 그대로 */
  --color-primary-700: #FF5F5B;  /* (추정) hover — 다크에선 밝아지는 방향 */
  --color-primary-800: #FF8A87;  /* (추정) pressed */
  --color-primary-900: #FFC0BE;  /* (추정) */

  /* Secondary - Heritage Red (로고 전용, 고정) + Warm Grey (다크 대응) */
  --color-secondary-500: #A50034;  /* 공식 Heritage Red — 테마 무관 */
  --color-warm-100: #1C1A17;       /* (추정) 웜 그레이 다크 면 */
  --color-warm-200: #24211D;       /* (추정) lg.com 웜 그레이 면의 다크 대응 */
  --color-warm-300: #34302A;       /* (추정) */
  --color-warm-500: #5C5750;       /* (추정) */
  --logo-wordmark: #FFFFFF;        /* 공식 흰색 로고 변형(LG_logo_footer_white.svg) */

  /* Neutral - 반전 (0 = 가장 어두움) */
  --color-neutral-0:    #0F0F0F;  /* 실측 lge.co.kr 사용값 — 다크 페이지 */
  --color-neutral-50:   #16171A;  /* (추정) */
  --color-neutral-100:  #1E2024;  /* (추정) 카드·이미지 영역 */
  --color-neutral-200:  #26282D;  /* (추정) */
  --color-neutral-300:  #33363B;  /* (추정) 구분선 */
  --color-neutral-500:  #767980;  /* navy04 */
  --color-neutral-600:  #8F9298;  /* navy05 */
  --color-neutral-700:  #BAC1C7;  /* navy07 */
  --color-neutral-800:  #DEE1E5;  /* navy09 */
  --color-neutral-900:  #F3F5F7;  /* navy11 — 본문 */
  --color-neutral-1000: #FFFFFF;

  /* Semantic */
  --color-success-bg: #10281A;  /* (추정) */
  --color-success-fg: #3CCB6A;  /* (추정) */
  --color-warning-bg: #2E2410;  /* (추정) */
  --color-warning-fg: #FFC940;  /* (추정) */
  --color-error-bg:   #2E1212;  /* (추정) */
  --color-error-fg:   #FF5F5B;  /* (추정) */
  --color-info-bg:    #0F2233;  /* (추정) */
  --color-info-fg:    #4DB5FF;  /* (추정) */

  /* Surface (배경 위계) */
  --bg-base: #0F0F0F;      /* 페이지 기본 */
  --bg-subtle: #1E2024;    /* 섹션·제품 이미지 영역 */
  --bg-warm: #24211D;      /* 웜 그레이 면의 다크 대응 (추정) */
  --bg-elevated: #1A1B1E;  /* 카드 (추정) */
  --bg-overlay: #26282D;   /* 모달·툴팁 (추정) */
  --bg-inverse: #F3F5F7;   /* 선택 칩 — 다크에선 밝은 칩 */

  /* Text 위계 */
  --text-primary: #F3F5F7;
  --text-secondary: #BAC1C7;
  --text-tertiary: #8F9298;
  --text-on-primary: #FFFFFF;
  --text-disabled: #555555;
  --text-price: #FD312E;

  /* Border */
  --border-default: #33363B;
  --border-subtle: #26282D;
  --border-strong: #F3F5F7;
  --border-focus: #FFFFFF;
}

/* 라이트 폴백 — 라이트 모드로 되돌릴 때 */
[data-theme="light"] {
  --color-primary-50: #FFF5F8; --color-primary-100: #FEE3E2; --color-primary-200: #FDC0BE; --color-primary-300: #FE8A87; --color-primary-400: #FF5F5B;
  --color-primary-500: #FD312E; --color-primary-600: #EA1917; --color-primary-700: #C4110F; --color-primary-800: #8E0E0C; --color-primary-900: #5C0907;
  --color-secondary-500: #A50034;
  --color-warm-100: #F6F3EB; --color-warm-200: #F0ECE4; --color-warm-300: #E6E1D6; --color-warm-500: #CBC8C2;
  --logo-wordmark: #707070;
  --color-neutral-0: #FFFFFF; --color-neutral-50: #F9FAFB; --color-neutral-100: #F3F5F7; --color-neutral-200: #ECEEF0; --color-neutral-300: #DEE1E5;
  --color-neutral-500: #8F9298; --color-neutral-600: #767980; --color-neutral-700: #43474D; --color-neutral-800: #212731; --color-neutral-900: #111111; --color-neutral-1000: #000000;
  --color-success-bg: #E7F6EC; --color-success-fg: #08A53A; --color-warning-bg: #FFF6D6; --color-warning-fg: #B26A00;
  --color-error-bg: #FEF3F3; --color-error-fg: #EA1917; --color-info-bg: #EAF5FF; --color-info-fg: #0C9AFF;
  --bg-base: #FFFFFF; --bg-subtle: #F3F5F7; --bg-warm: #F0ECE4; --bg-elevated: #FFFFFF; --bg-overlay: #FFFFFF; --bg-inverse: #111111;
  --text-primary: #111111; --text-secondary: #666666; --text-tertiary: #8F8F8F; --text-on-primary: #FFFFFF; --text-disabled: #BBBBBB; --text-price: #EA1917;
  --border-default: #DDDDDD; --border-subtle: #EEEEEE; --border-strong: #111111; --border-focus: #000000;
}


:root {
  --radius-none: 0;
  --radius-sm: 4px;      /* 실측 --br-radius--4 — 작은 배지 */
  --radius-md: 8px;      /* 실측 --br-radius--8 — 제품 썸네일·타임딜 바 */
  --radius-lg: 16px;     /* 실측 --br-radius--16 — 카드·배너 (lge.co.kr) */
  --radius-xl: 20px;     /* 실측 lg.com 1.25rem — 카드·툴팁 / 넓은 배너는 28px(1.75rem) */
  --radius-full: 9999px; /* 실측 62.4375rem·100px — 버튼·탭 칩(알약형) */
}

:root {
  --shadow-none: none;
  --shadow-sm: 0 0 1px 0 rgba(33,39,49,.28), 0 2px 8px 0 rgba(33,39,49,.05);   /* 실측 — 기본 카드 */
  --shadow-md: 0 2px 8px 0 rgba(33,39,49,.078), 0 0 1px 0 rgba(33,39,49,.361); /* 실측 — 카드 hover·드롭다운 */
  --shadow-lg: 2px 4px 12px 0 rgba(0,0,0,.16);                                 /* 실측 --box-shadow--base — 플로팅 버튼 */
  --shadow-xl: 0 12px 64px 0 rgba(0,0,0,.141), 0 0 1px 0 rgba(0,0,0,.078);     /* 실측 — 모달·검색 레이어 */
}

.btn { height: 48px; padding: 0 24px; border-radius: var(--radius-full); font: 700 16px/1 Pretendard, sans-serif; border: 1px solid transparent; transition: background var(--duration-fast) var(--ease-out), color var(--duration-fast); }
.btn-primary { background: var(--color-primary-600); border-color: var(--color-primary-600); color: var(--text-on-primary); }   /* .highlight */
.btn-primary:hover { background: var(--color-primary-700); border-color: var(--color-primary-700); }
.btn-primary:active { background: var(--color-primary-800); }
.btn-primary:disabled { background: var(--color-neutral-300); border-color: var(--color-neutral-300); color: var(--text-disabled); }
.btn-primary.is-loading { color: transparent; position: relative; } /* 가운데 흰 스피너 */
.btn-secondary { background: var(--bg-base); border-color: #646464; color: var(--text-primary); }                              /* 기본 */
.btn-secondary:hover { background: var(--color-primary-600); border-color: var(--color-primary-600); color: #fff; }             /* 실측 hover */
.btn-secondary:disabled { color: var(--color-warm-500); border-color: var(--color-warm-500); }
.btn-ghost { background: transparent; color: var(--text-primary); text-decoration: underline; text-underline-offset: 3px; }
.btn-ghost:hover { color: var(--color-primary-600); }
.btn-black { background: var(--bg-inverse); color: #fff; }  /* lge.co.kr 타임딜·선택 칩 */
.btn-danger { background: var(--bg-base); border-color: var(--color-error-fg); color: var(--color-error-fg); }
.btn-danger:hover { background: var(--color-error-bg); }
.input { height: 48px; padding: 0 16px; border: 1px solid var(--border-default); border-radius: var(--radius-md); background: var(--bg-base); font-size: 14px; color: var(--text-primary); }
.input:focus { border-color: var(--border-strong); outline: none; }
.input.is-error { border-color: var(--color-error-fg); }   /* 아래 12px 빨강 안내문 */
.input:disabled { background: var(--color-neutral-100); color: var(--text-disabled); }
.card { background: var(--bg-elevated); border-radius: var(--radius-lg); box-shadow: var(--shadow-sm); overflow: hidden; }       /* 기본 */
.card-product .thumb { background: var(--bg-subtle); border-radius: var(--radius-md); aspect-ratio: 1; }                           /* 제품 카드 */
.card-warm { background: var(--bg-warm); border-radius: var(--radius-xl); box-shadow: none; }                                      /* 강조형(lg.com) */
.card-outlined { background: var(--bg-base); border: 1px solid var(--border-subtle); border-radius: var(--radius-lg); box-shadow: none; }
.badge { height: 20px; padding: 0 6px; border-radius: var(--radius-sm); font-size: 11px; font-weight: 600; display: inline-flex; align-items: center; }
.badge-solid { background: var(--color-primary-600); color: #fff; }
.badge-subtle { background: var(--color-neutral-100); color: var(--color-neutral-700); }
.badge-outline { border: 1px solid var(--color-primary-600); color: var(--color-primary-600); }
.chip { height: 36px; padding: 0 16px; border-radius: var(--radius-full); border: 1px solid var(--border-default); font-size: 14px; }
.chip[aria-selected="true"] { background: var(--bg-inverse); border-color: var(--bg-inverse); color: var(--bg-base); font-weight: 600; }   /* 실측 */
.gnb { height: 72px; display: flex; align-items: center; gap: 32px; padding: 0 40px; background: var(--bg-base); border-bottom: 1px solid var(--border-subtle); }
.gnb a { font-size: 16px; font-weight: 500; color: var(--text-primary); height: 72px; display: flex; align-items: center; }
.gnb a[aria-current="page"] { font-weight: 700; box-shadow: inset 0 -2px 0 var(--border-strong); }
.gnb .count { min-width: 16px; height: 16px; border-radius: 100px; background: var(--color-primary-600); color: #fff; font-size: 10px; font-weight: 600; }  /* 장바구니 개수 — 실측 */

:root {
  --duration-fast: 150ms;   /* (추정) 버튼 색 전환 */
  --duration-base: 300ms;   /* (추정) 드롭다운·탭 */
  --duration-slow: 600ms;   /* (추정) 배너 슬라이드·로고 모션 */
  --ease-out: cubic-bezier(0.33, 1, 0.68, 1);    /* (추정) */
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1); /* (추정) */
}
